#ifndef HDLC_FCS_H
#define HDLC_FCS_H
#include <stddef.h>
#include <stdint.h>

#define HDLC_FCS16_INITIAL 0xffffu
#define HDLC_FCS16_GOOD 0xf0b8u
/* RFC 1662 sections 4.3/5.3: at least two body octets plus the FCS. */
#define HDLC_FCS16_MIN_FRAME_OCTETS 4

/* RFC 1662's reflected polynomial 0x8408, four bits per step. Each entry
 * is generated by four right shifts, XORing the polynomial for each set
 * low bit. This small table avoids a duplicated 256-entry byte table. */
static inline uint16_t hdlc_fcs16_update(uint16_t fcs, uint8_t octet)
{
	static const uint16_t remainder[16] = {
		0x0000, 0x1081, 0x2102, 0x3183,
		0x4204, 0x5285, 0x6306, 0x7387,
		0x8408, 0x9489, 0xa50a, 0xb58b,
		0xc60c, 0xd68d, 0xe70e, 0xf78f,
	};
	fcs ^= octet;
	fcs = (fcs >> 4) ^ remainder[fcs & 15u];
	return (fcs >> 4) ^ remainder[fcs & 15u];
}

/* Returned accumulator is not complemented. Transmit its complement,
 * low octet first; data followed by its FCS yields HDLC_FCS16_GOOD. */
static inline uint16_t hdlc_fcs16(const uint8_t *bytes, size_t count)
{
	uint16_t fcs = HDLC_FCS16_INITIAL;
	for (size_t i = 0; i < count; ++i)
		fcs = hdlc_fcs16_update(fcs, bytes[i]);
	return fcs;
}
#endif
